code='''def transform(grid):
    rows, cols = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rectangles = set()
    for top in range(rows):
        for color in set(grid[top]):
            valid = [True] * cols
            for bottom in range(top, rows):
                valid = [valid[c] and grid[bottom][c] == color for c in range(cols)]
                c = 0
                while c < cols:
                    if not valid[c]:
                        c += 1
                        continue
                    end = c
                    while end < cols and valid[end]:
                        end += 1
                    for left in range(c, end):
                        for right in range(left, end):
                            height, width = bottom - top + 1, right - left + 1
                            if height < 4 or width < 4 or height * width < 20:
                                continue
                            # Keep only rectangles that cannot be extended by one side.
                            if left > 0 and all(grid[r][left - 1] == color for r in range(top, bottom + 1)):
                                continue
                            if right + 1 < cols and all(grid[r][right + 1] == color for r in range(top, bottom + 1)):
                                continue
                            if top > 0 and all(grid[top - 1][k] == color for k in range(left, right + 1)):
                                continue
                            if bottom + 1 < rows and all(grid[bottom + 1][k] == color for k in range(left, right + 1)):
                                continue
                            rectangles.add((top, bottom, left, right))
                    c = end
    for top, bottom, left, right in rectangles:
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                out[r][c] = 4
    return out
'''
